window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6fa66181729680d4"]={"versions": [{"id": "FIG-6fa66181729680d4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der Metamodellierung und XML-Schema-Generierungsregeln gemäß AUTOSAR XML Schema Production Rules. Das Diagramm dient als abstraktes Beispiel-Metamodell zur Demonstration der Abbildungsregeln (Mapping Configuration) von Modellelementen, Kompositionsbeziehungen, Multiplizitäten und Vererbungshierarchien in XML-Schema-Definitionen (XSD).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert fünf Klassen:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Wurzel- bzw. Container-Klasse ohne explizite Attribute.\n</li><li><code>B</code>: Abstrakte Basisklasse (<code>{abstract}</code>, kursiver Klassenname) ohne eigene Attribute.\n</li><li><code>B1</code>: Konkrete Spezialisierung von <code>B</code> mit dem öffentlichen Attribut <code>+ attB1: String</code>.\n</li><li><code>B2</code>: Konkrete Spezialisierung von <code>B</code> mit dem öffentlichen Attribut <code>+ attB2: String</code>.\n</li><li><code>C</code>: Konkrete Klasse mit dem öffentlichen Attribut <code>+ attC: String</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen zwischen den Entitäten:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>A</code> nach <code>C</code>: Rolle <code>+theC</code>, Multiplizität genau 1 (<code>1</code>), ausgehend von <code>A</code> mit gefüllter Kompositionsraute.\n</li><li>Komposition von <code>A</code> nach <code>B</code>: Rolle <code>+theB</code>, Multiplizität beliebig (<code>*</code>), ausgehend von <code>A</code> mit gefüllter Kompositionsraute.\n</li><li>Generalisierung/Spezialisierung: <code>B1</code> und <code>B2</code> erben jeweils über einen offenen Dreieckspfeil von der abstrakten Klasse <code>B</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Zustandsübergangselemente. Das Diagramm spezifiziert die typisierte Instanziierungsstruktur: Instanzen von <code>A</code> besitzen aggregierend genau eine Instanz der Klasse <code>C</code> sowie eine beliebige Anzahl von polymorphen Instanzen der Spezialisierungen <code>B1</code> und <code>B2</code> über die abstrakte Schnittstelle <code>B</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normative Referenzarchitektur für die Fallunterscheidungen in <code>[TPS_XMLSPR_00038]</code> und folgenden Transformationsregeln der AUTOSAR XML Schema Production Rules:</p>\n<ul class=\"fig-list\"><li>Referenzfall für obere Multiplizität 1 ohne Subklassen: Eigenschaft <code>theC</code> (Typ <code>C</code> ohne Spezialisierungen) bedingt <code>xml.roleWrapperElement = false</code>, <code>xml.roleElement = true</code>, <code>xml.typeWrapperElement = false</code> und <code>xml.typeElement = false</code>.\n</li><li>Referenzfall für obere Multiplizität <code>*</code> mit Subklassen: Eigenschaft <code>theB</code> erfordert die Handhabung polymorpher Elemente (<code>B1</code>, <code>B2</code>) und Wrapper-Elemente für Multi-Instanz-Listen im generierten XML-Schema.\n</li></ul>"}, {"id": "FIG-d4010c38d62abd75", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der Metamodellierung und XML-Schema-Generierungsregeln gemäß AUTOSAR XML Schema Production Rules. Das Diagramm dient als abstraktes Beispiel-Metamodell zur Demonstration der Abbildungsregeln (Mapping Configuration) von Modellelementen, Kompositionsbeziehungen, Multiplizitäten und Vererbungshierarchien in XML-Schema-Definitionen (XSD).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert fünf Klassen:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Wurzel- bzw. Container-Klasse ohne explizite Attribute.\n</li><li><code>B</code>: Abstrakte Basisklasse (<code>{abstract}</code>, kursiver Klassenname) ohne eigene Attribute.\n</li><li><code>B1</code>: Konkrete Spezialisierung von <code>B</code> mit dem öffentlichen Attribut <code>+ attB1: String</code>.\n</li><li><code>B2</code>: Konkrete Spezialisierung von <code>B</code> mit dem öffentlichen Attribut <code>+ attB2: String</code>.\n</li><li><code>C</code>: Konkrete Klasse mit dem öffentlichen Attribut <code>+ attC: String</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen zwischen den Entitäten:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>A</code> nach <code>C</code>: Rolle <code>+theC</code>, Multiplizität genau 1 (<code>1</code>), ausgehend von <code>A</code> mit gefüllter Kompositionsraute.\n</li><li>Komposition von <code>A</code> nach <code>B</code>: Rolle <code>+theB</code>, Multiplizität beliebig (<code>*</code>), ausgehend von <code>A</code> mit gefüllter Kompositionsraute.\n</li><li>Generalisierung/Spezialisierung: <code>B1</code> und <code>B2</code> erben jeweils über einen offenen Dreieckspfeil von der abstrakten Klasse <code>B</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Zustandsübergangselemente. Das Diagramm spezifiziert die typisierte Instanziierungsstruktur: Instanzen von <code>A</code> besitzen aggregierend genau eine Instanz der Klasse <code>C</code> sowie eine beliebige Anzahl von polymorphen Instanzen der Spezialisierungen <code>B1</code> und <code>B2</code> über die abstrakte Schnittstelle <code>B</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normative Referenzarchitektur für die Fallunterscheidungen in <code>[TPS_XMLSPR_00038]</code> und folgenden Transformationsregeln der AUTOSAR XML Schema Production Rules:</p>\n<ul class=\"fig-list\"><li>Referenzfall für obere Multiplizität 1 ohne Subklassen: Eigenschaft <code>theC</code> (Typ <code>C</code> ohne Spezialisierungen) bedingt <code>xml.roleWrapperElement = false</code>, <code>xml.roleElement = true</code>, <code>xml.typeWrapperElement = false</code> und <code>xml.typeElement = false</code>.\n</li><li>Referenzfall für obere Multiplizität <code>*</code> mit Subklassen: Eigenschaft <code>theB</code> erfordert die Handhabung polymorpher Elemente (<code>B1</code>, <code>B2</code>) und Wrapper-Elemente für Multi-Instanz-Listen im generierten XML-Schema.\n</li></ul>"}, {"id": "FIG-6a408fb02a508559", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der Metamodellierung und XML-Schema-Generierungsregeln gemäß AUTOSAR XML Schema Production Rules. Das Diagramm dient als abstraktes Beispiel-Metamodell zur Demonstration der Abbildungsregeln (Mapping Configuration) von Modellelementen, Kompositionsbeziehungen, Multiplizitäten und Vererbungshierarchien in XML-Schema-Definitionen (XSD).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert fünf Klassen:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Wurzel- bzw. Container-Klasse ohne explizite Attribute.\n</li><li><code>B</code>: Abstrakte Basisklasse (<code>{abstract}</code>, kursiver Klassenname) ohne eigene Attribute.\n</li><li><code>B1</code>: Konkrete Spezialisierung von <code>B</code> mit dem öffentlichen Attribut <code>+ attB1: String</code>.\n</li><li><code>B2</code>: Konkrete Spezialisierung von <code>B</code> mit dem öffentlichen Attribut <code>+ attB2: String</code>.\n</li><li><code>C</code>: Konkrete Klasse mit dem öffentlichen Attribut <code>+ attC: String</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen zwischen den Entitäten:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>A</code> nach <code>C</code>: Rolle <code>+theC</code>, Multiplizität genau 1 (<code>1</code>), ausgehend von <code>A</code> mit gefüllter Kompositionsraute.\n</li><li>Komposition von <code>A</code> nach <code>B</code>: Rolle <code>+theB</code>, Multiplizität beliebig (<code>*</code>), ausgehend von <code>A</code> mit gefüllter Kompositionsraute.\n</li><li>Generalisierung/Spezialisierung: <code>B1</code> und <code>B2</code> erben jeweils über einen offenen Dreieckspfeil von der abstrakten Klasse <code>B</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Ablauf- oder Zustandsübergangselemente. Das Diagramm spezifiziert die typisierte Instanziierungsstruktur: Instanzen von <code>A</code> besitzen aggregierend genau eine Instanz der Klasse <code>C</code> sowie eine beliebige Anzahl von polymorphen Instanzen der Spezialisierungen <code>B1</code> und <code>B2</code> über die abstrakte Schnittstelle <code>B</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als normative Referenzarchitektur für die Fallunterscheidungen in <code>[TPS_XMLSPR_00038]</code> und folgenden Transformationsregeln der AUTOSAR XML Schema Production Rules:</p>\n<ul class=\"fig-list\"><li>Referenzfall für obere Multiplizität 1 ohne Subklassen: Eigenschaft <code>theC</code> (Typ <code>C</code> ohne Spezialisierungen) bedingt <code>xml.roleWrapperElement = false</code>, <code>xml.roleElement = true</code>, <code>xml.typeWrapperElement = false</code> und <code>xml.typeElement = false</code>.\n</li><li>Referenzfall für obere Multiplizität <code>*</code> mit Subklassen: Eigenschaft <code>theB</code> erfordert die Handhabung polymorpher Elemente (<code>B1</code>, <code>B2</code>) und Wrapper-Elemente für Multi-Instanz-Listen im generierten XML-Schema.\n</li></ul>"}], "trans": [{"from": "FIG-6fa66181729680d4", "to": "FIG-d4010c38d62abd75", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d4010c38d62abd75", "to": "FIG-6a408fb02a508559", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
